function getHomesteadDateFormat(setupConfig = {}) {
  return setupConfig?.displayPreferences?.dateFormat || setupConfig?.dateDisplayFormat || "MMM_D_YYYY";
}

function parseHomesteadDateParts(value) {
  if (!value) return null;

  if (value instanceof Date && !Number.isNaN(value.getTime())) {
    return { year: value.getFullYear(), month: value.getMonth() + 1, day: value.getDate() };
  }

  const raw = String(value).trim();
  if (!raw || raw === "—") return null;

  let match = raw.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);
  if (match) {
    return { year: Number(match[1]), month: Number(match[2]), day: Number(match[3]) };
  }

  match = raw.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{2,4})$/);
  if (match) {
    let year = Number(match[3]);
    if (year < 100) year += year > 30 ? 1900 : 2000;
    return { month: Number(match[1]), day: Number(match[2]), year };
  }

  const parsed = new Date(raw);
  if (!Number.isNaN(parsed.getTime())) {
    return { year: parsed.getFullYear(), month: parsed.getMonth() + 1, day: parsed.getDate() };
  }

  return null;
}

function padDatePart(value) {
  return String(value || "").padStart(2, "0");
}

function formatHomesteadDate(value, setupConfig = {}, fallback = "—") {
  const parts = parseHomesteadDateParts(value);
  if (!parts || !parts.month || !parts.day) return value || fallback;

  const format = getHomesteadDateFormat(setupConfig);
  const year = parts.year || "";
  const mm = padDatePart(parts.month);
  const dd = padDatePart(parts.day);
  const monthShort = new Date(2000, parts.month - 1, 1).toLocaleString(undefined, { month: "short" });

  if (!year && ["MM_DD_YYYY_DASH", "MM_DD_YYYY_SLASH", "YYYY_MM_DD_SLASH", "YYYY_MM_DD_DASH", "D_MMM_YYYY"].includes(format)) {
    return `${monthShort} ${parts.day}`;
  }

  switch (format) {
    case "MM_DD_YYYY_DASH":
      return `${mm}-${dd}-${year}`;
    case "MM_DD_YYYY_SLASH":
      return `${mm}/${dd}/${year}`;
    case "YYYY_MM_DD_SLASH":
      return `${year}/${mm}/${dd}`;
    case "YYYY_MM_DD_DASH":
      return `${year}-${mm}-${dd}`;
    case "D_MMM_YYYY":
      return `${parts.day} ${monthShort} ${year}`;
    case "MMM_D":
      return `${monthShort} ${parts.day}`;
    case "MMM_D_YYYY":
    default:
      return year ? `${monthShort} ${parts.day}, ${year}` : `${monthShort} ${parts.day}`;
  }
}

function getHomesteadHeightFormat(setupConfig = {}) {
  return setupConfig?.displayPreferences?.heightFormat || setupConfig?.heightDisplayFormat || "FT_IN_DASH";
}

function getHomesteadWeightFormat(setupConfig = {}) {
  return setupConfig?.displayPreferences?.weightFormat || setupConfig?.weightDisplayFormat || "LBS";
}

function parseHomesteadHeightInches(value) {
  if (value === undefined || value === null || String(value).trim() === "") return null;
  if (typeof value === "number" && Number.isFinite(value)) return value > 100 ? value / 2.54 : value;

  const raw = String(value).trim().toLowerCase();
  if (!raw || raw === "—") return null;

  const cmMatch = raw.match(/(\d+(?:\.\d+)?)\s*cm/);
  if (cmMatch) return Number(cmMatch[1]) / 2.54;

  const ftInMatch = raw.match(/(\d+)\s*(?:ft|feet|'|’|′)\s*[- ]?\s*(\d+(?:\.\d+)?)?/);
  if (ftInMatch) return (Number(ftInMatch[1]) * 12) + Number(ftInMatch[2] || 0);

  const inchesMatch = raw.match(/(\d+(?:\.\d+)?)\s*(?:in|inch|inches|"|”|″)/);
  if (inchesMatch) return Number(inchesMatch[1]);

  const numeric = Number(raw.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(numeric) || numeric <= 0) return null;
  return numeric > 100 ? numeric / 2.54 : numeric;
}

function formatHomesteadHeight(value, setupConfig = {}, fallback = "—") {
  const inches = parseHomesteadHeightInches(value);
  if (!inches) return value || fallback;

  const format = getHomesteadHeightFormat(setupConfig);
  if (format === "INCHES") return `${Math.round(inches)}\"`;
  if (format === "CM") return `${Math.round(inches * 2.54)} cm`;

  const feet = Math.floor(inches / 12);
  const remaining = Math.round(inches - (feet * 12));
  return `${feet}'-${remaining}\"`;
}

function parseHomesteadWeightLbs(value) {
  if (value === undefined || value === null || String(value).trim() === "") return null;
  if (typeof value === "number" && Number.isFinite(value)) return value;

  const raw = String(value).trim().toLowerCase();
  if (!raw || raw === "—") return null;

  const kgMatch = raw.match(/(\d+(?:\.\d+)?)\s*kg/);
  if (kgMatch) return Number(kgMatch[1]) * 2.2046226218;

  const lbMatch = raw.match(/(\d+(?:\.\d+)?)\s*(?:lb|lbs|pound|pounds)/);
  if (lbMatch) return Number(lbMatch[1]);

  const numeric = Number(raw.replace(/[^0-9.]/g, ""));
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function formatHomesteadWeight(value, setupConfig = {}, fallback = "—") {
  const lbs = parseHomesteadWeightLbs(value);
  if (!lbs) return value || fallback;

  const format = getHomesteadWeightFormat(setupConfig);
  if (format === "KG") return `${Math.round(lbs / 2.2046226218)} kg`;
  return `${Math.round(lbs)} lbs`;
}

