const PROFILE_METADATA_TOP_LEVEL_MIRROR_KEYS = [
  "privateNotes",
  "profilePrivateNotes",
  "profileNotes",
  "privateNoteCards",
  "profileNotesUpdatedAt",
  "biography",
  "description",
  "notes",
  "profileFacts",
  "profileFactsUpdatedAt",
  "timeline",
  "timelineEntries",
  "profileTimeline",
];

function mergeAdultLoadedMetadata(baseMetadata = {}, metadataFile = {}) {
  const mirrored = {};
  for (const key of PROFILE_METADATA_TOP_LEVEL_MIRROR_KEYS) {
    if (Object.prototype.hasOwnProperty.call(metadataFile || {}, key)) {
      mirrored[key] = metadataFile[key];
    }
  }
  return {
    ...(baseMetadata || {}),
    ...mirrored,
    ...((metadataFile || {}).metadata || {}),
  };
}

async function fetchJsonIfExists(path, options = {}) {
  try {
    const bustCache = options.bustCache !== false;
    const separator = String(path || "").includes("?") ? "&" : "?";
    const url = bustCache ? `${path}${separator}v=${Date.now()}` : path;
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

function normalizeMetadataPathToMediaUrl(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  let clean = raw.replace(/\\/g, "/").replace(/\/+/g, "/");
  const mediaIndex = clean.indexOf("/media/");
  if (mediaIndex >= 0) clean = clean.slice(mediaIndex);
  if (clean.startsWith("media/")) clean = `/${clean}`;
  if (!clean.startsWith("/media/")) return "";
  if (!clean.toLowerCase().endsWith("metadata.json")) {
    clean = `${clean.replace(/\/$/, "")}/metadata.json`;
  }
  return encodeURI(clean);
}

async function fetchFirstJsonIfExists(paths = []) {
  const seen = new Set();
  for (const path of paths) {
    const normalized = normalizeMetadataPathToMediaUrl(path);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    const data = await fetchJsonIfExists(normalized);
    if (data) {
      return { data, path: normalized };
    }
  }
  return { data: null, path: "" };
}

