function isAdultProfileMetadataVerified(profile) {
  const metadata = profile?.metadata || {};
  const match = metadata.metadataMatch || profile?.metadataMatch || {};
  const providerIds = metadata.providerIds || metadata.externalIds || {};

  return Boolean(
    metadata.profileVerified ||
    metadata.metadataVerified ||
    metadata.verified ||
    metadata.verifiedAt ||
    metadata.matchVerified ||
    metadata.matchVerifiedAt ||
    match.verified ||
    match.verifiedAt ||
    match.matchedAt ||
    match.providerId ||
    metadata.wikidataId ||
    metadata.imdbId ||
    metadata.tmdbId ||
    Object.values(providerIds).filter(Boolean).length
  );
}

