    appleMusic: { label: "Apple Music", icon: "♫", color: "red" },
    soundcloud: { label: "SoundCloud", icon: "☁", color: "orange" },
    officialwebsite: { label: "Official Website", icon: "🌐", color: "neutral" },
    officialsite: { label: "Official Website", icon: "🌐", color: "neutral" },
    modelsite: { label: "Model Site / Portfolio", icon: "★", color: "purple" },
