    tumblr: { label: "Tumblr", icon: "t", color: "blue" },
    reddit: { label: "Reddit", icon: "r/", color: "orange" },
    twitch: { label: "Twitch", icon: "◩", color: "purple" },
    patreon: { label: "Patreon", icon: "P", color: "orange" },
    onlyfans: { label: "OnlyFans", icon: "★", color: "cyan" },
    fansly: { label: "Fansly", icon: "★", color: "blue" },
