          <label><span>Photo grid transparency</span><input type="range" min="0" max="1" step="0.01" value={1 - values.photoGridOpacity} onInput={(event) => updateNumber("photoGridOpacity", 1 - Number(event.currentTarget.value))} onChange={(event) => updateNumber("photoGridOpacity", 1 - Number(event.currentTarget.value))} /><strong>{Math.round((1 - values.photoGridOpacity) * 100)}%</strong></label>
