{tab === "scenes" && (
  <PerformerSceneGrid
    person={viewPerson}
    fallbackFiles={profileMediaFiles}
    targetLibrary={profileImportLibrary}
    onScenesFetched={(scenes, data) => {
      setLivePerson((current) => {
        const base = current || viewPerson;
        const existingCandidates = base.metadataCandidates || {};
        const existingScenes = Array.isArray(existingCandidates.scenes) ? existingCandidates.scenes : [];
        const seen = new Set();
        const mergedScenes = [...scenes, ...existingScenes].filter((scene) => {
          const key = String(scene.providerId || scene.id || scene.url || scene.sourceUrl || scene.title || "").toLowerCase();
          if (!key || seen.has(key)) return false;
          seen.add(key);
          return true;
        });
        return {
          ...base,
          metadataCandidates: {
            ...existingCandidates,
            scenes: mergedScenes,
          },
        };
      });
      setProfileMediaActionStatus(data?.message || `Fetched ${scenes.length} Eporner scene references.`);
      window.dispatchEvent(new CustomEvent("homestead-adult-profile-updated", {
        detail: {
          reason: "eporner-scenes-fetched",
          profileId: viewPerson.id || person.id,
          profileName: viewPerson.name || person.name,
          libraryType: profileImportLibrary,
          scenes,
        },
      }));
      window.dispatchEvent(new Event("homestead-metadata-match-updated"));
    }}
  />
)}

