function parseEpisodeName(filename) {
  const clean = filename.replace(/\.(mp4|mov|mkv|avi|webm|m4v)$/i, "");

  const match = clean.match(/S(\d{1,2})E(\d{1,2})\s*(.*)/i);

  if (!match) {
    return {
      code: "",
      title: clean,
    };
  }

  return {
    code: `S${match[1].padStart(2, "0")}E${match[2].padStart(2, "0")}`,
    title: match[3] || clean,
  };
}

