function getTmdbImageUrl(path, size = "w780") {
  if (!path) return "";

  if (String(path).startsWith("http")) {
    return path;
  }

  return `https://image.tmdb.org/t/p/${size}${path}`;
}

function getNormalizedTmdbCardImage(
  item = {},
  mediaType = "movie",
  preference = "poster"
) {
  const metadata = normalizeTmdbMetadata(item, mediaType);

  if (preference === "backdrop") {
    return metadata.backdrop || metadata.poster || "";
  }

  return metadata.poster || metadata.backdrop || "";
}

const HOMESTEAD_METADATA_MATCHES_KEY = "homesteadMetadataMatches";

function normalizeMetadataMatchAlias(value = "") {
  return String(value || "")
    .replaceAll("\\", "/")
    .trim()
    .toLowerCase()
    .replace(/\?.*$/, "")
    .replace(/\/metadata\.json$/i, "")
    .replace(/\/poster\.(jpg|jpeg|png|webp)$/i, "")
    .replace(/\/banner\.(jpg|jpeg|png|webp)$/i, "")
    .replace(/\/folder\.(jpg|jpeg|png|webp)$/i, "")
    .replace(/\/cover\.(jpg|jpeg|png|webp)$/i, "")
    .replace(/\/+/g, "/")
    .replace(/^\/+|\/+$/g, "");
}

function slugMetadataMatchAlias(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function cleanMetadataSearchQuery(value = "") {
  return String(value || "")
    .replace(/\b(?:19|20)\d{2}\b/g, " ")
    .replace(/\b(?:720|1080|2160|480)p\b/gi, " ")
    .replace(/\b(?:x264|x265|h264|h265|hevc|bluray|blu-ray|brrip|webrip|web-dl|webdl|dvdrip|remux|proper|repack|hdr|uhd|4k)\b/gi, " ")
    .replace(/[()[\]{}._-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}function uniqueMetadataMatchAliases(values = []) {
  const seen = new Set();
  const aliases = [];

  for (const value of values.flat(Infinity)) {
    if (value === undefined || value === null) continue;
    const raw = String(value || "").trim();
    if (!raw) continue;

    const normalized = normalizeMetadataMatchAlias(raw);
    const slug = slugMetadataMatchAlias(raw.split("/").pop() || raw);

    for (const candidate of [raw, normalized, slug]) {
      const clean = String(candidate || "").trim();
      if (!clean || seen.has(clean)) continue;
      seen.add(clean);
      aliases.push(clean);
    }
  }

  return aliases;
}

function buildMetadataLocalIdAliases(item = {}) {
  const original = item.originalItem || item.localItem || {};
  const metadata = item.metadata || original.metadata || {};
  const names = [
    item.localId,
    item.id,
    item.path,
    item.filePath,
    item.folderPath,
    item.sourcePath,
    item.name,
    item.title,
    item.displayTitle,
    item.folderName,
    item.fileName,
    item.filename,
    original.localId,
    original.id,
    original.path,
    original.filePath,
    original.folderPath,
    original.sourcePath,
    original.name,
    original.title,
    original.folderName,
    original.fileName,
    original.filename,
    metadata.title,
    metadata.name,
    metadata.sortTitle,
    metadata.tmdbId && `tmdb:${metadata.tmdbId}`,
    metadata.providerId && `provider:${metadata.providerId}`,
  ];

  const pathValues = [item.path, item.filePath, item.folderPath, item.sourcePath, original.path, original.filePath, original.folderPath, original.sourcePath].filter(Boolean);
  for (const value of pathValues) {
    const parts = String(value || "").replaceAll("\\", "/").split("/").filter(Boolean);
    if (parts.length) names.push(parts[parts.length - 1]);
    if (parts.length > 1) names.push(parts.slice(-2).join("/"));
  }

  return uniqueMetadataMatchAliases(names);
}

function getMetadataMatchKeys(libraryType, itemOrLocalId = "") {
  const aliases = typeof itemOrLocalId === "object"
    ? buildMetadataLocalIdAliases(itemOrLocalId)
    : uniqueMetadataMatchAliases([itemOrLocalId]);

  return aliases.map((alias) => `${libraryType}:${alias}`);
}

function loadHomesteadMetadataMatches() {
  try {
    return JSON.parse(
      localStorage.getItem(HOMESTEAD_METADATA_MATCHES_KEY) || "{}"
    );
  } catch {
    return {};
  }
}

function saveHomesteadMetadataMatch(libraryType, localId, metadata, localItem = null) {
  const matches = loadHomesteadMetadataMatches();
  const canonicalLocalId = localId || getMetadataLocalId(localItem || {});
  const aliases = uniqueMetadataMatchAliases([
    canonicalLocalId,
    ...(Array.isArray(metadata?.aliases) ? metadata.aliases : []),
    ...(localItem ? buildMetadataLocalIdAliases(localItem) : []),
  ]);
  const key = `${libraryType}:${canonicalLocalId}`;

  const savedRecord = {
    ...metadata,
    libraryType,
    localId: canonicalLocalId,
    aliases,
    matchedAt: metadata?.matchedAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  matches[key] = savedRecord;

  for (const alias of aliases) {
    matches[`${libraryType}:${alias}`] = {
      ...savedRecord,
      aliasOf: key,
    };
  }

  localStorage.setItem(
    HOMESTEAD_METADATA_MATCHES_KEY,
    JSON.stringify(matches)
  );

  return savedRecord;
}

function getHomesteadMetadataMatch(libraryType, itemOrLocalId) {
  const matches = loadHomesteadMetadataMatches();
  const keys = getMetadataMatchKeys(libraryType, itemOrLocalId);

  for (const key of keys) {
    if (matches[key]) return matches[key];
  }

  return null;
}

async function syncHomesteadMetadataMatchesFromServer() {
  try {
    const res = await fetch("/api/metadata/matches");
    const data = await res.json();

    if (!res.ok || data.ok === false) {
      throw new Error(data.message || "Failed to load metadata matches");
    }

    const serverMatches = data.matches || {};
    const localMatches = loadHomesteadMetadataMatches();
    const mergedMatches = {
      ...localMatches,
      ...serverMatches,
    };

    localStorage.setItem(
      HOMESTEAD_METADATA_MATCHES_KEY,
      JSON.stringify(mergedMatches)
    );

    return mergedMatches;
  } catch (error) {
    console.error("Failed to sync metadata matches from server:", error);
    return loadHomesteadMetadataMatches();
  }
}

async function saveHomesteadMetadataMatchToServer(
  libraryType,
  localId,
  metadata,
  localItem = null
) {
  const res = await fetch("/api/metadata/match", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      libraryType,
      localId,
      metadata,
      localItem,
    }),
  });

  const data = await res.json();

  if (!res.ok || data.ok === false) {
    throw new Error(data.message || "Failed to save metadata match");
  }

  return data.match;
}

async function searchHomesteadMetadata(libraryType, query) {
  const params = new URLSearchParams({
    libraryType,
    query: String(query || "").trim(),
  });

  const res = await fetch(`/api/metadata/search?${params.toString()}`);
  const data = await res.json();

  if (!res.ok || data.ok === false) {
    throw new Error(data.message || "Metadata search failed");
  }

  return data;
}

function getLocalApiFileUrl(path) {
  if (!path) return "";

  const raw = String(path || "").trim();
  if (!raw) return "";
  if (/^(https?:|blob:|data:)/i.test(raw)) return raw;
  if (raw.startsWith("/api/file")) return raw;

  return `/api/file?path=${encodeURIComponent(raw)}`;
}

function firstDefined(...values) {
  return values.find((value) => value != null && String(value).trim() !== "") || "";
}

function getMetadataLocalId(item = {}) {
  const aliases = buildMetadataLocalIdAliases(item);
  return (
    item.localId ||
    item.id ||
    item.path ||
    item.filePath ||
    item.folderPath ||
    item.sourcePath ||
    aliases[0] ||
    item.name ||
    item.title ||
    item.displayTitle ||
    ""
  );
}

function getMatchedPosterOrLocalPoster(
  libraryType,
  item,
  fallback = "/placeholder-poster.jpg"
) {
  const localId = getMetadataLocalId(item);
  const savedMatch = getHomesteadMetadataMatch(libraryType, item) || getHomesteadMetadataMatch(libraryType, localId);

  if (savedMatch?.poster) {
    return savedMatch.poster;
  }

  if (item.poster) {
    return getLocalApiFileUrl(item.poster);
  }

  if (item.posterPath) {
    return getTmdbImageUrl(item.posterPath, "w500");
  }

  return fallback;
}

function getMatchedBannerOrLocalBanner(
  libraryType,
  item,
  fallback = "/placeholder-banner.jpg"
) {
  const localId = getMetadataLocalId(item);
  const savedMatch = getHomesteadMetadataMatch(libraryType, item) || getHomesteadMetadataMatch(libraryType, localId);

  if (savedMatch?.backdrop) {
    return savedMatch.backdrop;
  }

  if (item.banner) {
    return getLocalApiFileUrl(item.banner);
  }

  if (item.backdropPath) {
    return getTmdbImageUrl(item.backdropPath, "original");
  }

  if (item.poster) {
    return getLocalApiFileUrl(item.poster);
  }

  if (savedMatch?.poster) {
    return savedMatch.poster;
  }

  return fallback;
}


function getTrailerCandidateFromDetails(mediaDetails, detailItem, item) {
  const pools = [
    mediaDetails?.videos,
    mediaDetails?.trailers,
    mediaDetails?.results,
    mediaDetails?.item?.videos,
    mediaDetails?.item?.trailers,
    detailItem?.videos,
    detailItem?.trailers,
    detailItem?.trailer,
    item?.videos,
    item?.trailers,
    item?.trailer,
  ];

  const flat = pools
    .flatMap((value) => {
      if (!value) return [];
      if (Array.isArray(value)) return value;
      if (Array.isArray(value?.results)) return value.results;
      if (typeof value === "string") return [{ url: value }];
      return [value];
    })
    .filter(Boolean);

  return (
    flat.find((video) => /trailer/i.test(video.type || video.name || video.title || "")) ||
    flat.find((video) => /youtube|youtu\.be/i.test(video.site || video.url || video.key || "")) ||
    flat[0] ||
    null
  );
}

function buildTrailerSource(trailer) {
  if (!trailer) return null;

  const site = String(trailer.site || "").toLowerCase();
  const key = trailer.key || trailer.videoKey || trailer.youtubeKey;
  const url = trailer.url || trailer.src || trailer.path;

  if ((site === "youtube" || site.includes("youtube")) && key) {
    return {
      kind: "iframe",
      title: trailer.name || trailer.title || "Trailer",
      src: `https://www.youtube.com/embed/${key}?autoplay=1&playsinline=0&rel=0`,
    };
  }

  if (key && !url) {
    return {
      kind: "iframe",
      title: trailer.name || trailer.title || "Trailer",
      src: `https://www.youtube.com/embed/${key}?autoplay=1&playsinline=0&rel=0`,
    };
  }

  if (url && /youtube\.com|youtu\.be/i.test(url)) {
    let videoId = "";
    try {
      const parsed = new URL(url);
      videoId = parsed.hostname.includes("youtu.be")
        ? parsed.pathname.replace(/^\//, "")
        : parsed.searchParams.get("v") || "";
    } catch (err) {
      videoId = "";
    }

    if (videoId) {
      return {
        kind: "iframe",
        title: trailer.name || trailer.title || "Trailer",
        src: `https://www.youtube.com/embed/${videoId}?autoplay=1&playsinline=0&rel=0`,
      };
    }
  }

  if (url) {
    return {
      kind: /\.(mp4|webm|mov|m4v)(\?|$)/i.test(url) ? "video" : "external",
      title: trailer.name || trailer.title || "Trailer",
      src: url,
    };
  }

  return null;
}

