function buildDashboardRecentlyAdded(mediaIndex) {
  const items = [];

  function addItems(list, type, icon) {
    if (!Array.isArray(list)) return;

    list.forEach((item) => {
      items.push({
        title:
          item.title ||
          item.name ||
          item.artist ||
          item.displayName ||
          item.filename ||
          "Untitled",
        type,
        icon,
        addedAt:
          item.addedAt ||
          item.createdAt ||
          item.updatedAt ||
          item.modifiedAt ||
          item.lastModified ||
          "",
      });
    });
  }

  addItems(mediaIndex?.movies, "Movie", "🎬");
  addItems(mediaIndex?.tvShows || mediaIndex?.tv, "TV Show", "📺");
  addItems(mediaIndex?.books, "Book", "📚");
  addItems(mediaIndex?.musicArtists || mediaIndex?.music, "Music", "🎵");
  addItems(mediaIndex?.youtubeCreators || mediaIndex?.youtube, "YouTube", "▶️");
  addItems(mediaIndex?.photos, "Photo", "🖼️");

  return items.sort((a, b) => {
    const aTime = a.addedAt ? new Date(a.addedAt).getTime() : 0;
    const bTime = b.addedAt ? new Date(b.addedAt).getTime() : 0;

    return bTime - aTime;
  });
}

