function cleanDashboardMediaTitle(value = "", libraryType = "media") {
  let title = String(value || "")
    .replace(/\\/g, "/")
    .split("/")
    .pop()
    .replace(/\.(mkv|mp4|m4v|mov|avi|webm|mp3|flac|m4a|aac|ogg|wav|epub|pdf|cbz|cbr|jpg|jpeg|png|webp)$/i, "")
    .replace(/[_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  // Strip common downloader / archive cruft without touching normal titles.
  title = title
    .replace(/\[[^\]]*(?:1080p|720p|2160p|4k|x264|x265|h\.264|h\.265|web[- ]?dl|bluray|aac|dts|yts|rarbg|eztv|psa|hevc)[^\]]*\]/gi, "")
    .replace(/\((?:19|20)\d{2}\)\s*(?:-|–)?\s*$/g, "")
    .replace(/\b(?:1080p|720p|2160p|4k|x264|x265|h\.264|h\.265|web[- ]?dl|bluray|webrip|brrip|hdrip|dvdrip|aac|dts|hevc)\b/gi, "")
    .replace(/\b[a-f0-9]{12,}\b/gi, "")
    .replace(/\s+/g, " ")
    .replace(/\s+[-–]\s*$/g, "")
    .trim();

  if (libraryType === "tv" || libraryType === "youtube") {
    title = title.replace(/\bS(\d{1,2})E(\d{1,2})\b\s*[-–:]?\s*/i, (match, season, episode) => {
      const suffix = title.replace(match, "").trim();
      return suffix ? `S${season.padStart(2, "0")}E${episode.padStart(2, "0")} · ` : `S${season.padStart(2, "0")}E${episode.padStart(2, "0")}`;
    });
  }

  if (libraryType === "book") {
    title = title
      .replace(/\s+--\s+.*$/g, "")
      .replace(/\s+-\s+(?:[^-]+)$/g, (match) => (/\bby\b/i.test(match) ? "" : match));
  }

  title = title
    .replace(/\s{2,}/g, " ")
    .replace(/\s+([:;,.!?])/g, "$1")
    .trim();

  return title || "Untitled";
}

function getDashboardMediaSubtitle(item = {}, libraryType = "media", suppliedSubtitle = "") {
  const subtitle = suppliedSubtitle || item.subtitle || item.artist || item.creatorName || item.series || item.showTitle || "";
  if (!subtitle) return "";
  const cleanSubtitle = cleanDashboardMediaTitle(subtitle, libraryType);
  const cleanTitle = cleanDashboardMediaTitle(item.title || item.name || item.filename || "", libraryType);
  return cleanSubtitle && cleanSubtitle !== cleanTitle ? cleanSubtitle : "";
}

function getDashboardFallbackIcon(libraryType = "media") {
  const icons = {
    movie: "🎬",
    movies: "🎬",
    tv: "📺",
    tvshows: "📺",
    book: "📚",
    books: "📚",
    music: "🎵",
    youtube: "▶️",
    liveTV: "📡",
    livetv: "📡",
    photos: "🖼️",
    adult: "🔞",
    inventory: "📦",
    cloud: "☁️",
    ai: "✨",
  };

  return icons[libraryType] || "🏠";
}

function HomeDashboardMiniPosterCard({
  item = {},
  title,
  subtitle,
  poster,
  libraryType = "media",
  progress = null,
  progressLabel = "",
  onClick,
}) {
  const [imageFailed, setImageFailed] = useState(false);
  const rawTitle = title || item.title || item.name || item.filename || "Untitled";
  const displayTitle = cleanDashboardMediaTitle(rawTitle, libraryType);
  const displaySubtitle = getDashboardMediaSubtitle(item, libraryType, subtitle);
  const posterSource = poster || item.poster || item.cover || item.thumb || item.thumbnail || item.image || "";
  const hasPoster = !!posterSource && !imageFailed;
  const progressValue = Number.isFinite(progress) ? Math.max(0, Math.min(100, progress)) : null;

  return (
    <button
      className={`mini-poster-card mini-poster-card-${libraryType}`}
      type="button"
      onClick={onClick}
      title={displayTitle}
    >
      <div className={`mini-poster-art ${hasPoster ? "" : "mini-poster-art-fallback"}`}>
        {hasPoster ? (
          <img
            src={getLocalApiFileUrl(posterSource)}
            alt=""
            loading="lazy"
            onError={() => setImageFailed(true)}
          />
        ) : (
          <div className="mini-poster-fallback-card">
            <span className="mini-poster-fallback-icon">
              {getDashboardFallbackIcon(libraryType)}
            </span>
            <strong>{displayTitle}</strong>
          </div>
        )}
      </div>

      <div className="continue-card-info">
        {progressValue != null && (
          <div className="continue-progress-track">
            <div
              className="continue-progress-fill"
              style={{ width: `${progressValue}%` }}
            />
          </div>
        )}

        {progressLabel && <small>{progressLabel}</small>}
        <span>{displayTitle}</span>
        {displaySubtitle && <small>{displaySubtitle}</small>}
      </div>
    </button>
  );
}

