function BookReader({ file, book, onClose }) {
  const readerRef = useRef(null);
  const renditionRef = useRef(null);
  const touchStartRef = useRef(null);

  const goPrevPage = () => {
    renditionRef.current?.prev?.();
  };

  const goNextPage = () => {
    renditionRef.current?.next?.();
  };

  const handleBookTouchStart = (event) => {
    const touch = event.touches?.[0];
    if (!touch) return;

    touchStartRef.current = {
      x: touch.clientX,
      y: touch.clientY,
      time: Date.now(),
    };
  };

  const handleBookTouchEnd = (event) => {
    const start = touchStartRef.current;
    const touch = event.changedTouches?.[0];
    touchStartRef.current = null;

    if (!start || !touch) return;

    const deltaX = touch.clientX - start.x;
    const deltaY = touch.clientY - start.y;
    const elapsed = Date.now() - start.time;

    if (Math.abs(deltaX) > 55 && Math.abs(deltaX) > Math.abs(deltaY) * 1.35 && elapsed < 900) {
      if (deltaX < 0) goNextPage();
      else goPrevPage();
    }
  };

  const handleBookTap = (event) => {
    if (!readerRef.current) return;

    const bounds = readerRef.current.getBoundingClientRect();
    const x = event.clientX - bounds.left;
    const leftZone = bounds.width * 0.22;
    const rightZone = bounds.width * 0.78;

    if (x <= leftZone) goPrevPage();
    if (x >= rightZone) goNextPage();
  };

  useEffect(() => {
    if (!file || !readerRef.current) return;

    let cancelled = false;
    let epubBook = null;
    let rendition = null;

    async function loadBook() {
      const savedProgress = getWatchProgress()[book?.id];

      epubBook = ePub(file.path);

      await epubBook.ready;
      await epubBook.locations.generate(1000);

      if (cancelled || !readerRef.current) return;

      rendition = epubBook.renderTo(readerRef.current, {
        width: "100%",
        height: "100%",
      });

      renditionRef.current = rendition;

      await rendition.display(savedProgress?.location || undefined);

      rendition.on("relocated", (location) => {
        const percentage =
          epubBook.locations.percentageFromCfi(location.start.cfi) || 0;

        saveWatchProgress(book.id, {
          type: "book",
          title: book.title,
          author: book.author,
          poster: book.poster,
          path: file.path,
          fileName: file.name,
          location: location.start.cfi,
          percentage,
          currentTime: percentage,
          duration: 1,
        });
      });
    }

    loadBook();

    return () => {
      cancelled = true;

      if (rendition) {
        rendition.destroy();
      }

      if (epubBook) {
        epubBook.destroy();
      }
    };
  }, [file, book]);

  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "ArrowLeft") goPrevPage();
      if (event.key === "ArrowRight") goNextPage();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  return (
    <div className="book-reader-overlay">
      <div className="book-reader-toolbar">
        <button className="secondary-button" onClick={onClose}>
          Close
        </button>

        <button
          className="secondary-button"
          onClick={goPrevPage}
        >
          ← Prev
        </button>

        <strong>{book?.title || file.name}</strong>

        <button
          className="secondary-button"
          onClick={goNextPage}
        >
          Next →
        </button>
      </div>

      <div
        ref={readerRef}
        className="book-reader-view book-reader-touch-view"
        onTouchStart={handleBookTouchStart}
        onTouchEnd={handleBookTouchEnd}
        onClick={handleBookTap}
      />
    </div>
  );
}

