function buildRecentWatchlistItems(mediaIndex, watchlist) {
  const moviesById = Object.values(mediaIndex?.libraries?.movies || {}).reduce(
    (acc, item) => {
      acc[item.id] = {
        id: item.id,
        title: item.name || item.title,
        mediaType: "movie",
        label: "Movie",
        year: item.metadata?.year || "",
        poster: item.poster
          ? `/api/file?path=${encodeURIComponent(item.poster)}`
          : "/placeholder-poster.jpg",
        detailItem: {
          id: item.id,
          title: item.name || item.title,
          poster: item.poster
            ? `/api/file?path=${encodeURIComponent(item.poster)}`
            : "/placeholder-poster.jpg",
          banner: item.banner
            ? `/api/file?path=${encodeURIComponent(item.banner)}`
            : item.poster
            ? `/api/file?path=${encodeURIComponent(item.poster)}`
            : "/placeholder-banner.jpg",
          trailer:
            item.trailer ||
            item.files?.find((file) =>
              file.name.toLowerCase().includes("trailer")
            )?.path ||
            "",
          year: item.metadata?.year || "",
          genres: item.metadata?.genres || [],
          description: item.metadata?.description || "No description available.",
          files: item.files || [],
          counts: item.counts || {},
          collections: item.metadata?.collections || [],
        },
      };

      return acc;
    },
    {}
  );

  const tvById = Object.values(mediaIndex?.libraries?.tv || {}).reduce(
    (acc, item) => {
      acc[item.id] = {
        id: item.id,
        title: item.name || item.title,
        mediaType: "tv",
        label: "TV Show",
        year: item.metadata?.year || "",
        poster: item.poster
          ? `/api/file?path=${encodeURIComponent(item.poster)}`
          : "/placeholder-poster.jpg",
        detailItem: {
          id: item.id,
          title: item.name || item.title,
          poster: item.poster
            ? `/api/file?path=${encodeURIComponent(item.poster)}`
            : "/placeholder-poster.jpg",
          banner: item.banner
            ? `/api/file?path=${encodeURIComponent(item.banner)}`
            : item.poster
            ? `/api/file?path=${encodeURIComponent(item.poster)}`
            : "/placeholder-banner.jpg",
          trailer:
            item.trailer ||
            item.files?.find((file) =>
              file.name.toLowerCase().includes("trailer")
            )?.path ||
            "",
          year: item.metadata?.year || "",
          genres: item.metadata?.genres || [],
          description: item.metadata?.description || "No description available.",
          files: item.files || [],
          counts: item.counts || {},
        },
      };

      return acc;
    },
    {}
  );

  const movieItems = [...(watchlist?.movies || [])]
    .reverse()
    .map((id) => moviesById[id])
    .filter(Boolean);

  const tvItems = [...(watchlist?.tv || [])]
    .reverse()
    .map((id) => tvById[id])
    .filter(Boolean);

  return [...movieItems, ...tvItems].slice(0, 8);
}

