function getAdultDiscoveryDisplayGroup(result = {}) {
  const type = String(result.profileType || result.libraryType || result.resultGroup || "").toLowerCase();
  if (type.includes("celeb")) return "celebrity";
  if (type.includes("personal")) return "personal";
  return "performer";
}

function isJunkAdultDiscoveryResult(result = {}) {
  const title = String(result.title || result.name || "").trim().toLowerCase();
  const subtitle = String(result.subtitle || "").trim().toLowerCase();
  if (!title) return true;
  return [
    /^invalid$/,
    /^model not found$/,
    /^not found$/,
    /^page not found$/,
    /model not found/,
    /404 not found/,
    /page not found/,
  ].some((pattern) => pattern.test(`${title} ${subtitle}`));
}

function cleanAdultDiscoveryResults(results = []) {
  const seen = new Set();
  return (Array.isArray(results) ? results : [])
    .filter((result) => result && !isJunkAdultDiscoveryResult(result))
    .filter((result) => {
      const key = `${result.libraryType || result.profileType || "adult"}:${result.provider || result.source || "source"}:${result.sourceCandidateId || result.url || result.externalUrl || result.name || result.title}`.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function getAdultDiscoveryProviderKey(result = {}) {
  return String(result.provider || result.source || result.sourceLabel || "").toLowerCase().trim();
}

function getAdultDiscoveryNameKey(result = {}) {
  return String(result.title || result.name || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function isMainstreamAdultDiscoveryProvider(result = {}) {
  const provider = getAdultDiscoveryProviderKey(result);
  return /tmdb|wikidata|wikipedia|imdb|models\.com|models-com|fashion-model-directory|fashion model directory/.test(provider);
}

function isStrongCelebrityAdultDiscoveryResult(result = {}) {
  if (getAdultDiscoveryDisplayGroup(result) !== "celebrity") return false;
  const confidence = Number(result.confidence || 0);
  const score = Number(result.matchScore || 0);
  return isMainstreamAdultDiscoveryProvider(result) && (confidence >= 0.6 || score >= 70 || result.wikidataId || result.tmdbId || result.imdbId);
}

function suppressDuplicateAdultDiscoveryCrossTypes(results = []) {
  const cleaned = cleanAdultDiscoveryResults(results);
  const strongCelebrityNames = new Set(
    cleaned
      .filter(isStrongCelebrityAdultDiscoveryResult)
      .map(getAdultDiscoveryNameKey)
      .filter(Boolean)
  );

  if (!strongCelebrityNames.size) return cleaned;

  return cleaned.filter((result) => {
    const group = getAdultDiscoveryDisplayGroup(result);
    if (group !== "performer") return true;
    const nameKey = getAdultDiscoveryNameKey(result);

    // If Wikidata/Wikipedia/TMDB/IMDb already produced a strong celebrity match
    // for the same name, do not repeat that same mainstream identity result as a
    // performer. Performer-specific sources can still appear when they are real.
    if (strongCelebrityNames.has(nameKey) && isMainstreamAdultDiscoveryProvider(result)) {
      return false;
    }

    return true;
  });
}

function groupAdultDiscoveryResults(results = []) {
  return suppressDuplicateAdultDiscoveryCrossTypes(results).reduce((groups, result) => {
    const group = getAdultDiscoveryDisplayGroup(result);
    if (!groups[group]) groups[group] = [];
    groups[group].push(result);
    return groups;
  }, { celebrity: [], personal: [], performer: [] });
}

function getAdultDiscoverySectionTitle(groupKey = "performer") {
  if (groupKey === "celebrity") return "Celebrity Sources";
  if (groupKey === "personal") return "Personal Profile Sources";
  return "Performer Sources";
}

function getAdvancedPersonSearchLabel(query = "") {
  const cleanQuery = String(query || "").trim();
  return cleanQuery ? `Advanced Person Search for “${cleanQuery}”` : "Advanced Person Search";
}

function getBrowseContentLabel(query = "") {
  const cleanQuery = String(query || "").trim();
  return cleanQuery ? `Browse Content for “${cleanQuery}”` : "Browse Content";
}

