useEffect(() => {
  let cancelled = false;

  fetch("/api/intake/library-records/inventory", {
    headers: { Accept: "application/json" },
    cache: "no-store",
  })
    .then((response) => response.json())
    .then((data) => {
      if (cancelled) return;
      const records = Array.isArray(data?.records) ? data.records : [];

      setInventorySearchItems(
        records.map((record) => {
          const tcg = record.tcg || {};
          const isTcg =
            String(record.category || "").toLowerCase() === "trading-cards";

          return {
            id: record.id,
            title: record.title || record.name || tcg.cardName || "Untitled inventory item",
            subtitle: isTcg
              ? [tcg.setCode, tcg.rarity, `$${Number(tcg.marketValue || 0).toFixed(2)}`]
                  .filter(Boolean)
                  .join(" • ")
              : record.notes || record.category || "Inventory item",
            type: isTcg ? "tcg-card" : "inventory-item",
            library: "inventory",
            icon: isTcg ? "🃏" : "📦",
            status: "owned",
            poster: isTcg ? getTcgCardImage(record) : (
              record.captures?.find((capture) => capture?.dataUrl)?.dataUrl ||
              record.metadata?.thumbnail ||
              record.poster ||
              ""
            ),
            searchText: [
              record.title,
              record.name,
              record.code,
              record.notes,
              record.category,
              tcg.cardName,
              tcg.setCode,
              tcg.rarity,
              tcg.condition,
              tcg.attribute,
              tcg.race,
              tcg.selectedPrinting?.type,
              tcg.selectedPrinting?.race,
              tcg.selectedPrinting?.attribute,
              ...(Array.isArray(tcg.binders) ? tcg.binders : []),
              ...(Array.isArray(tcg.deckBuilds) ? tcg.deckBuilds : []),
            ]
              .filter(Boolean)
              .join(" ")
              .toLowerCase(),
            record,
          };
        })
      );
    })
    .catch(() => {
      if (!cancelled) setInventorySearchItems([]);
    });

  return () => {
    cancelled = true;
  };
}, [metadataMatchesVersion]);

