useEffect(() => {
  if (!searchText) {
    setSeerrResults([]);
    setYoutubeSearchResults([]);
    setAdultDiscoveryResults([]);
    return;
  }

  const timeout = setTimeout(() => {
    if (canSearchMovies || canSearchTv) {
      const seerrParams = new URLSearchParams({
  query: searchText,
});

fetch(`/api/integrations/seerr/search?${seerrParams.toString()}`)
        .then((res) => res.json())
        .then((data) => {
          const results = data.results || [];

          setSeerrResults(
            results.filter((item) =>
              item.mediaType === "tv" ? canSearchTv : canSearchMovies
            )
          );
        })
        .catch((err) => {
          console.error("Seerr search failed:", err);
          setSeerrResults([]);
        });
    } else {
      setSeerrResults([]);
    }

    if (canSearchYoutube) {
      fetch(
        `/api/youtube/search/channels?q=${encodeURIComponent(searchText)}`
      )
        .then((res) => res.json())
        .then((data) => {
          setYoutubeSearchResults(data.results || []);
        })
        .catch(() => {
          setYoutubeSearchResults([]);
        });
    } else {
      setYoutubeSearchResults([]);
    }

    if (canSearchAdult) {
      fetch(`/api/metadata/adult/person/search?q=${encodeURIComponent(searchText)}&profileType=both`)
        .then((res) => res.json())
        .then((data) => {
          if (!data?.ok) {
            setAdultDiscoveryResults([]);
            return;
          }

          setAdultDiscoveryResults(
            cleanAdultDiscoveryResults(
              (data.results || data.candidates || []).map((result) => ({
                ...result,
                id: result.id || `${result.libraryType || result.profileType || "adult"}-${result.sourceCandidateId || result.url || result.name || searchText}`,
                title: result.title || result.name || searchText,
                subtitle: result.subtitle || `${result.profileType === "celebrity" ? "Celebrity" : "Performer"} • ${result.source || result.provider || "External source"}`,
                icon: result.icon || (result.profileType === "celebrity" ? "🌟" : "🔎"),
                status: "external",
              }))
            )
          );
        })
        .catch(() => setAdultDiscoveryResults([]));
    } else {
      setAdultDiscoveryResults([]);
    }
  }, 300);

  return () => clearTimeout(timeout);
}, [searchText, canSearchMovies, canSearchTv, canSearchYoutube, canSearchAdult]);

